from collections import Counter as Ct, defaultdict
def solve(g, bc):
    h,w=len(g),len(g[0])
    bg=Ct(x for row in g for x in row).most_common(1)[0][0]
    # detect box period: try offsets; assume boxes 3x3 here / generalized s=4 for demo2? Use per-demo known sizes; instead detect via periodicity of inner pattern.
    def inner_val(bi,bj,s):
        cnt=Ct(g[ro+bi*5+r][co+bj*5+c] for r in range(1,s) for c in range(1,s))
        cc=[k for k,v in cnt.items() if k not in (bc,bg)]
        return max(cc,key=lambda k:cnt[k]) if cc else None
    # search offsets & size s from {3,4}
    best=None
    for s in (3,4):
        for ro in range(s):
            for co in range(s):
                # must fit at least one full band-row and band-col with pattern periodic
                if (h-1-s)%5 or (w-1-s)%5: continue
                ok=True
                for bi in range((h-s)//5):
                    for bj in range((w-s)//5):
                        v=inner_val(bi,bj,s)
                        if v is None and True: pass
                # just accept if all interior cells equal single color? relax: require no mixed non-bc-non-bg
                bad=False
                for bi in range((h-s)//5):
                    for bj in range((w-s)//5):
                        vals={g[ro+bi*5+r][co+bj*5+c] for r in range(1,s) for c in range(1,s)}-{bg,bc}
                        if len(vals)>1: bad=True
                if not bad: best=(ro,co,s);break
            if best:break
        if best:break
    ro,co,s=best
    m=[[inner_val(bi,bj,s) for bj in range((w-s)//5)] for bi in range((h-s)//5)]
    D=defaultdict(list)
    for bi in range(len(m)):
        for bj in range(len(m[0])):
            v=m[bi][bj]
            if v is not None: D[v].append((bi,bj))
    out=[row[:] for row in g]
    painted=set()
    for c,blocks in D.items():
        rs=sorted({b[0] for b in blocks}); cs=sorted({b[1] for b in blocks})
        for a in range(len(rs)-1):
            for j in range(co+cs[0]*5+2, co+cs[-1]*5-1):
